def find_path(graph, start, goal):
    """
    Implement a path search (a form of graph traversal) to find a path from
    the start to the goal in the given graph. If there's no path, return None.
    """

    # Initialize the stack with pairs of which node we've visited and the path to get there.
    stack = [(start, [start])]
    visited = set()

    while stack:
        (current, path) = stack.pop()

        if current not in visited:
            visited.add(current)
            if current == goal:
                return path

            for neighbour in graph[current]:
                if neighbour not in visited:
                    stack.append((neighbour, path + [neighbour]))

    return None
