import heapq

def heuristic(a, b):
    # Simple heuristic (Euclidean distance) between two nodes
    return ((b[0] - a[0]) ** 2 + (b[1] - a[1]) ** 2) ** 0.5

def find_path(graph, start, goal):
    # Using a dictionary to store unvisited nodes with their f, g, and h values
    frontier = []
    visited = set()
    parents = {start: None}
    g_score = {node: float('infinity') for node in graph}
    f_score = {node: float('infinity') for node in graph}
    g_score[start] = 0
    f_score[start] = heuristic(start, goal)

    heapq.heappush(frontier, (f_score[start], start))

    while frontier:
        current = heapq.heappop(frontier)[1]

        if current == goal:
            path = []
            while current is not None:
                path.append(current)
                current = parents[current]
            return path[::-1]  # Return the path from start to goal

        visited.add(current)

        for neighbor in graph[current]:
            if neighbor in visited:
                continue
            tentative_g_score = g_score[current] + 1  # Assuming all edges have cost 1

            if neighbor not in visited:
                parents[neighbor] = current
                g_score[neighbor] = tentative_g_score
                f_score[neighbor] = tentative_g_score + heuristic(neighbor, goal)
                if neighbor not in [node[1] for node in frontier]:
                    heapq.heappush(frontier, (f_score[neighbor], neighbor))
            elif tentative_g_score >= g_score[neighbor]:
                continue

    return None  # Return None if there is no path
